mapper.update:
update orders
customer_id=#{customerId}, address_id=#{addressId}, station_id=#{stationId}, delivery_station_id=#{deliveryStationId}, settle_station_id=#{deliveryStationId}, delivery_staff_id=#{deliveryStaffId}, source=#{source}, status=#{status}, payment_method=#{paymentMethod}, payment_status=#{paymentStatus}, total_amount=#{totalAmount}, water_amount=#{waterAmount}, deposit_amount=#{depositAmount}, delivery_fee=#{deliveryFee}, floor_fee=#{floorFee}, receiver_name=#{receiverName}, receiver_phone=#{receiverPhone}, address_snapshot=#{addressSnapshot}, address_snapshot_lat=#{addressSnapshotLat}, address_snapshot_lng=#{addressSnapshotLng}, guard_info=#{guardInfo}, delivery_time_request=#{deliveryTimeRequest}, special_note=#{specialNote}, delivery_bucket_qty=#{deliveryBucketQty}, return_bucket_qty=#{returnBucketQty}, barrel_discrepancy=#{barrelDiscrepancy}, barrel_discrepancy_note=#{barrelDiscrepancyNote}, first_barrel_order=#{firstBarrelOrder}, idempotency_key=#{idempotencyKey}, barrel_exception_id=#{barrelExceptionId}, exception_flag=#{exceptionFlag}, exception_category=#{exceptionCategory}, exception_count=#{exceptionCount}, update_time=NOW()
where id=#{id}

mapper.select:
select o.*, c.name as customerName, c.phone as customerPhone,
       a.detail as addressDetail, a.name as addressName, a.phone as addressPhone,
       a.lat as addressLat, a.lng as addressLng,
       (select oi.product_name_snapshot from order_item oi where oi.order_id = o.id order by oi.id limit 1) as firstProductName
from orders o
left join customer c on o.customer_id = c.id
left join address a on o.address_id = a.id


        and o.station_id = #{stationId}


        and o.customer_id = #{customerId}


        and o.status = #{status}


        and o.create_time >= #{createTimeStart}


        and o.create_time <= #{createTimeEnd}


order by o.create_time desc


    limit #{limit}

        offset #{offset}
